 static int checks;static readonly BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Instance;
 static void Check(bool valid,string message){checks++;if(!valid)throw new Exception("FLOOR_LOBBY_VISUAL: "+message);}
 public static void Validate(){checks=0;foreach(var pane in new[]{new Vector2(375,627),new Vector2(430,839),new Vector2(734,343),new Vector2(280,580)})foreach(var language in new[]{"de","en"})Fixture(pane,language);Debug.Log("FLOOR_LOBBY_VISUAL_PASS checks="+checks);}
 static void Fixture(Vector2 pane,string language){var root=new GameObject("FloorLobbyVisualFixture");Canvas canvas=null;try{var course=root.AddComponent<FloorCourse>();var profile=new FloorProfile{Language=language,UnlockedRealm=2,TimingVersion=1,Crystals=428,Style=1};profile.Styles[1]=true;profile.Normalize();typeof(FloorCourse).GetField("<Profile>k__BackingField",Private).SetValue(course,profile);course.Player=new GameObject("Player").transform;course.Player.SetParent(root.transform);var hud=root.AddComponent<FloorHud>();hud.Initialize(course);var safe=(RectTransform)typeof(FloorHud).GetField("_safe",Private).GetValue(hud);canvas=safe.GetComponentInParent<Canvas>();canvas.GetComponent<CanvasScaler>().enabled=false;canvas.scaleFactor=3;UiMetrics.QaPointScale=3;safe.GetComponent<SafeAreaFitter>().enabled=false;safe.anchorMin=safe.anchorMax=Vector2.one*.5f;safe.sizeDelta=pane;typeof(FloorHud).GetMethod("Layout",Private).Invoke(hud,null);var modal=typeof(FloorHud).GetField("_modal",Private);UnityEngine.Object.DestroyImmediate(((RectTransform)modal.GetValue(hud)).gameObject);modal.SetValue(hud,null);hud.ShowHome();Canvas.ForceUpdateCanvases();var content=safe.Find("ModalBackdrop/ModalCard/Viewport/Content");var viewport=(RectTransform)content.parent;var backdrop=safe.Find("ModalBackdrop/AtriumBackdrop");Check(backdrop!=null,"lobby is a full spatial atrium rather than an inset framed showroom");var room=backdrop.GetComponent<RawImage>();Check(room!=null&&!room.raycastTarget,"atrium backdrop never owns navigation input");Check(UiMetrics.ScreenRect((RectTransform)backdrop)==UiMetrics.ScreenRect(safe),"room fills actual safe area without stretching an inset preview");var actual=content.Find("TowerPreview/LiftElevation").GetComponent<LiftScenePreview>();Check(room.texture==actual.texture,"full room shares the owned cached scene target without a second camera");Check(actual.SceneRoot.transform.Find("GrandAtriumArchitecture")!=null,"lobby includes authored complete room architecture");var roomCamera=actual.SceneRoot.GetComponentInChildren<Camera>();foreach(var renderer in actual.SceneRoot.transform.Find("CopperLiftCabin").GetComponentsInChildren<Renderer>()){var bounds=renderer.bounds;foreach(float x in new[]{bounds.min.x,bounds.max.x})foreach(float y in new[]{bounds.min.y,bounds.max.y})foreach(float z in new[]{bounds.min.z,bounds.max.z}){var corner=roomCamera.WorldToViewportPoint(new Vector3(x,y,z));Check(corner.x>=0&&corner.x<=1,"full carriage is not cut off by the room's left or right edge");}}var hero=(RectTransform)content.Find("TowerPreview");Check(hero.rect.height/viewport.rect.height>=.65f,pane+" architectural composition uses available height instead of a small banner");var geometries=new HashSet<string>();float previous=-1;for(int i=0;i<3;i++){var card=(RectTransform)content.Find("Realm"+i);float y=-card.anchoredPosition.y;Check(y>previous,pane+" chapters form three readable scenic rows");previous=y;Check(card.rect.height>=49&&card.rect.width>=100,pane+" chapter row has useful picturesque area");var scene=card.Find("ChapterIllustration").GetComponent<LiftScenePreview>().SceneRoot;var signature=new List<string>();foreach(var mesh in scene.GetComponentsInChildren<MeshFilter>()){long hash=17;foreach(var vertex in mesh.sharedMesh.vertices){var p=scene.transform.InverseTransformPoint(mesh.transform.TransformPoint(vertex));unchecked{hash=hash*31+Mathf.RoundToInt(p.x*100);hash=hash*31+Mathf.RoundToInt(p.y*100);hash=hash*31+Mathf.RoundToInt(p.z*100);}}signature.Add(mesh.sharedMesh.vertexCount+":"+hash);}signature.Sort();geometries.Add(string.Join("|",signature));Check(scene.GetComponentsInChildren<Collider>().Length==0,"scenic menu architecture never supplies a gameplay collider");}Check(geometries.Count==3,"chapters change actual skyline geometry, rather than only colors");var symbols=new HashSet<string>();foreach(var glyph in content.GetComponentsInChildren<FloorLobbyGlyph>()){using(var vertices=new VertexHelper()){typeof(FloorLobbyGlyph).GetMethod("OnPopulateMesh",Private,null,new[]{typeof(VertexHelper)},null).Invoke(glyph,new object[]{vertices});var mesh=new Mesh();try{vertices.FillMesh(mesh);long hash=17;foreach(var v in mesh.vertices)unchecked{hash=hash*31+Mathf.RoundToInt(v.x*100);hash=hash*31+Mathf.RoundToInt(v.y*100);}symbols.Add(mesh.vertexCount+":"+hash);}finally{UnityEngine.Object.DestroyImmediate(mesh);}}}Check(symbols.Count==6,"utility destinations have six genuinely distinct symbol meshes");Check(profile.Crystals==428&&profile.Style==1&&profile.Step==0&&course.Paused,"menu composition retains wallet, style, progress and pause");UnityEngine.Object.DestroyImmediate(((RectTransform)modal.GetValue(hud)).gameObject);modal.SetValue(hud,null);hud.ShowCheckpoint();Canvas.ForceUpdateCanvases();var choice=safe.Find("ModalBackdrop/ModalCard");var currentPreview=choice.Find("Viewport/Content/FloorComparison/CurrentFloor/ChapterIllustration").GetComponent<LiftScenePreview>();var nextPreview=choice.Find("Viewport/Content/FloorComparison/NextFloor/ChapterIllustration").GetComponent<LiftScenePreview>();Check(currentPreview.SceneRoot.transform.Find("CopperLiftCabin")!=null,"risk compares the real current carriage instead of a repeated city postcard");Check(nextPreview.SceneRoot.transform.Find("CopperLiftCabin")==null&&nextPreview.SceneRoot.transform.Find("ArchitecturalFloorBay")!=null,"next choice depicts its own adjoining balcony");Check(currentPreview.SceneRoot.GetComponentInChildren<TextMesh>().text=="1"&&nextPreview.SceneRoot.GetComponentInChildren<TextMesh>().text=="2","risk previews carry actual consecutive floor numbers");Check(currentPreview.SceneRoot.GetComponentsInChildren<Collider>().Length==0&&nextPreview.SceneRoot.GetComponentsInChildren<Collider>().Length==0,"risk images are presentation only");Check(choice.Find("Bank").GetComponent<Image>().material!=null,"bank retains the shaped warm action surface");}finally{UiMetrics.QaPointScale=null;if(canvas!=null)UnityEngine.Object.DestroyImmediate(canvas.gameObject);UnityEngine.Object.DestroyImmediate(root);}}
}
